/**
 * Executed projects — PDF chapter "Executed Projects" (road, dam and building tables + photo pages).
 *
 * HOW TO ADD A PROJECT: append an object to `roads`, `dams` or `buildings` below.
 *  - `no` is the row number in the source table.
 *  - `utm` is optional: UTM Zone 38N (WGS84) easting/northing in metres, as printed on the photos.
 *    lat/lng is computed automatically at build time (see `withLatLng`).
 *  - `images` reference slugs in public/images (generated by scripts/process-images.py).
 */
import proj4 from 'proj4';
import type { L } from './types';

export type ProjectType = 'road' | 'dam' | 'building';

export interface Project {
  id: string;
  type: ProjectType;
  /** Row number in the PDF table. Photo-only road sections have none. */
  no?: string;
  name: L;
  governorate: L;
  district: L;
  /** Dam type, building scope, or road scope. */
  detail: L;
  lengthKm?: number;
  utm?: { e: number; n: number };
  images: { slug: string; alt: L }[];
  /** Road sections documented with aerial photos + coordinates but not listed as table rows. */
  section?: boolean;
  /*
   * Private client names are intentionally NOT published.
   * To show them, uncomment `client` here and in the project entries below, then render it in ProjectCard.
   */
  // client?: string;
}

export interface ProjectWithGeo extends Project {
  latLng?: [number, number];
}

