// ——— Derived data ———

const utm38n = '+proj=utm +zone=38 +datum=WGS84 +units=m +no_defs +type=crs';

function withLatLng(p: Project): ProjectWithGeo {
  if (!p.utm) return p;
  const [lng, lat] = proj4(utm38n, 'WGS84', [p.utm.e, p.utm.n]);
  return { ...p, latLng: [Number(lat.toFixed(5)), Number(lng.toFixed(5))] };
}

export const projects: ProjectWithGeo[] = [...roads, ...dams, ...buildings].map(withLatLng);

/** Table rows only (excludes photo-documented road sections). */
export const tabled = {
  roads: roads.filter((r) => !r.section),
  dams,
  buildings,
};

/** Sum of the lengths given in the road table (rows 01–13). */
export const tabledRoadKm = Number(tabled.roads.reduce((s, r) => s + (r.lengthKm ?? 0), 0).toFixed(1));

export const featuredProjectIds = ['hassan-dam', 'al-sawaida-komal', 'fcom-hq-aden'] as const;

export const formatUtm = (u: { e: number; n: number }) =>
  `E ${Math.round(u.e).toString()} · N ${Math.round(u.n).toString()}`;
